  "settings.modelProvider.fieldHelp": "{field} hakkında",
  "settings.modelProvider.help.contextWindow":
    "Modelin bir seferde işleyebildiği bağlam kapasitesi, token cinsinden. ZCode bunu bağlamı yönetmek için kullanır.\nModelin gerçek sınırını aşmayın.",
  "settings.modelProvider.help.maxOutputTokens":
    "Tek bir model isteğinin üretebileceği en fazla token sayısı.\nModelin gerçek sınırını aşmayın.",
  "settings.modelProvider.help.inputModalities":
    "Modelin alabileceği içerik türlerini ayarlayın:\n\n- **Metin**: Metin içeriği alır. Zorunlu.\n- **Görseller**: Görsel içeriği alır.\n- **Video**: Video içeriği alır.\n- **PDF**: PDF belgelerini doğrudan alır.",
  "settings.modelProvider.help.outputModalities":
    "Model yanıtlarının içerik türü. Şu anda yalnızca metin destekleniyor.",
  "settings.modelProvider.help.capabilities":
    "- **Yapılandırılmış çıktı**: Çıktı alanları, türleri ve yapısı üzerinde JSON Schema kısıtlarını destekler.\n- **Yerel web araması**: Model API'sinin yerleşik web arama yeteneğini destekler.\n- **Sohbet ortası sistem mesajları**: Sohbet sırasında sistem talimatı eklemeyi destekler.\n\nModelin desteklemediği yetenekleri açmayın.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "Sohbette kullanılabilir akıl yürütme düzeylerini ayarlayın. **En düşükten en yükseğe akıl yürütme çabasına göre sıralanmış olmalıdır**.\nModelin desteklemediği akıl yürütme düzeylerini yapılandırmayın.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "Geçerli akıl yürütme düzeyini (`reasoningLevel`) model API istek alanlarına eşlemek için bir CEL ifadesi kullanın. İfadenin döndürdüğü JSON nesnesi giden istek gövdesine birleştirilir.",
  "settings.modelProvider.help.advanced":
    "**MFJS araç şeması**: Moonshot'un Kimi model API'sinin yaygın kullandığı Moonshot Flavored JSON Schema uyumluluğunu açar. Yalnızca model API'si bu biçimi gerektiriyorsa açın.",
  "settings.modelProvider.help.followRecommendedConfig":
    "Model ID, Base URL ve API biçimini kullanarak önerilen yapılandırmayla eşleşir. ZCode önerileri sürekli günceller ve otomatik olarak size eşitler.\nBir ayarı elle değiştirdiğinizde o ayar elle yönetilen hale gelir ve öneri güncellemelerini izlemeyi bırakır; diğer ayarlar akıllı yapılandırma yönetiminde kalır.",
